Translate("ruRU", "the-deadmines", {
	title = "Мертвые копи",
	aliases = { "Копи" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мертвые копи лежат под деревней {link:moonbrook}Луноречье{/link} в {link:westfall}Западном Крае{/link}. Некогда это были богатейшие золотые рудники в землях людей. Теперь это тайное сердце {link:defias-brotherhood}Братства Справедливости{/link}. В их глубинах каменщики, которых ведет {link:edwin-vancleef}Эдвин ван Клиф{/link}, и нанятые ими гоблины строят то, чего в {link:stormwind-city}Штормград{/link}е еще никто не видел: большой боевой корабль, укрытый в морской пещере на самом дне копей.]=],
		},
		{
			title = "Истоки",
			text = [=[Многие поколения рудники под {link:moonbrook}Луноречье{/link}м слали золото в казну {link:kingdom-of-stormwind}королевства Штормград{/link}. Когда {link:horde}Орда{/link} разрушила {link:stormwind-city}Штормград{/link} в {link:first-war}Первую войну{/link}, рудокопы бежали, и выработки затихли. Туннели остались во власти тьмы, и народ стал звать их Мертвыми копями. Они пустовали все годы изгнания и восстановления. Когда преданные каменщики пришли на запад, они нашли уже вырытую для них крепость.]=],
		},
		{
			title = "Наши дни",
			text = [=[Братство сделало старый рудник своим святилищем. В его шахтах копают рудокопы Братства, а его залы стерегут волшебники и заклинатели Братства. Гоблины-мастеровые и инженеры, нанятые Братством, рубят лес, плавят металл и собирают машины. Первые ворота стережет {link:ogres}огр{/link}. Далеко внизу, где туннели выходят к морю, корабль почти готов, а его капитан и команда ждут приказа своего господина. Что {link:edwin-vancleef}ван Клиф{/link} намерен с ним делать, знает только Братство. Многие боятся, что корабль предназначен для {link:stormwind-city}Штормград{/link}а.]=],
		},
		{
			title = "В глубине копей",
			text = [=[• {b}Обрушенное крыло.{/b} Перед входом во владения Братства боковой проход ведет к туннелям, где при обвале свода был п{link:ogres}огр{/link}ебен отряд {link:dwarves}дворф{/link}ов — рудокопов и исследователей. Покоя они не обрели. Их мертвецы до сих пор бродят во тьме с кирками и динамитом.
• {b}Мачтовый зал.{/b} Здесь гоблины, которыми командует начальник лесорубов {link:sneed}Снид{/link}, тешут огромные брусья для корабля.
• {b}Литейная.{/b} Здесь гоблин {link:gilnid}Гилнид{/link} плавит металл копей.
• {b}{link:ironclad-cove}Потайная бухта{/link}.{/b} На дне копей лежит пещера, открытая морю, и в ней стоит на якоре корабль Братства. Ворота в нее запечатаны, и открыть их могут только порох и пушка.
• {b}Скрытый выход.{/b} Из бухты проход поднимается к холмам за {link:moonbrook}Луноречье{/link}м, близ моря.]=],
		},
		{
			title = "Те, кто обитает внизу",
			text = [=[Слуг у Братства здесь много. Бригадир {link:rhahkzor}Рак'Зор{/link}, гоблины {link:sneed}Снид{/link} и {link:gilnid}Гилнид{/link} и команда корабля под началом капитана Зеленокожего — все они подчиняются одному человеку, и это {link:edwin-vancleef}Эдвин ван Клиф{/link}. В туннелях таятся и более редкие опасности, и среди них — рудокоп {link:ogres}огр{/link}омной силы, известный как рудокоп Джонсон.]=],
		},
	},
})

Translate("ruRU", "ironclad-cove", {
	title = "Потайная бухта",
	sections = {
		{
			title = "Обзор",
			text = [=[Потайная бухта — {link:ogres}огр{/link}омная морская пещера на дне Мертвых копей, где туннели старых золотых рудников выходят к Великому морю. Здесь {link:defias-brotherhood}Братство Справедливости{/link} хранит свою главную тайну. На темной воде стоит на якоре боевой корабль, построенный из леса, обтесанного в Мачтовом зале, и металла, выплавленного в Литейной. Его команда — пираты Братства. С его верхней палубы {link:edwin-vancleef}Эдвин ван Клиф{/link} повелевает всем своим Братством, и именно здесь он решил дать бой.]=],
		},
	},
})

Translate("ruRU", "edwin-vancleef", {
	title = "Эдвин ван Клиф",
	subtitle = "Главарь Братства Справедливости",
	found = "Верхняя палуба корабля в Потайной бухте",
