	allegiance = "Братство Справедливости · прежде Гильдия каменщиков",
	aliases = { "ван Клиф", "Эдвин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Эдвин ван Клиф был главой {link:stonemasons-guild}Гильдии каменщиков{/link} {link:stormwind-city}Штормград{/link}а. Именно его гильдия подняла столицу из пепла {link:first-war}Первой войны{/link}. Когда работа была окончена, {link:house-of-nobles}Палата знати{/link} отказалась заплатить каменщикам то, что им причиталось. Ван Клиф поднял их на бунт и покинул город, поклявшись отомстить. Теперь он главарь {link:defias-brotherhood}Братства Справедливости{/link} и хозяин {link:westfall}Западного Края{/link}, и из потайной бухты под землей он готовит удар по королевству, которое его предало.]=],
		},
		{
			title = "Значение",
			text = [=[Ван Клиф — рана, которую {link:stormwind-city}Штормград{/link} нанес себе сам. Он был строителем, а не разбойником, и те, кто его знал, помнят человека одаренного и трудолюбивого. Его Братство родилось из подлинной несправедливости. Но его месть тяжелее всего легла на простой народ Западного Края, а не на знать, которая его обманула, и она довела до разорения житницу самого королевства.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он вел Гильдию каменщиков при восстановлении {link:stormwind-city}Штормград{/link}а после войн.
• Когда некоторым старшим каменщикам предложили должности в правительстве, он отказался от своей из верности всей гильдии.
• Он возглавил бунт каменщиков и в конце его бежал из города. В этой смуте была убита королева {link:tiffin-wrynn}Тиффин Ринн{/link}.
• Он собрал изгнанных каменщиков в Западном Крае и основал {link:defias-brotherhood}Братство Справедливости{/link}.
• Он сделал {link:the-deadmines}Мертвые копи{/link} своей твердыней и нанял гоблинов, чтобы построить в их глубинах боевой корабль.
• Его помощник {link:bazil-thredd}Базиль Тредд{/link} был схвачен и заключен в {link:the-stockade}Тюрьму{/link} Штормграда.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит о том, когда родился ван Клиф, о его семье и о годах до того, как он стал главой гильдии. Эта запись хранит лишь его деяния и слова тех, кто его знал.]=],
		},
	},
	chapters = {
		{
			title = "Имя из прошлого",
			hint = "Отнесите вопрос о каменщиках в SI:7.",
			text = [=[Долгое время у Братства не было лица. Потом {link:master-mathias-shaw}Матиас Шоу{/link} из {link:si-7}SI:7{/link} дал ему лицо. Старую гильдию каменщиков, писал он, возглавлял Эдвин ван Клиф — человек, который отстроил {link:stormwind-city}Штормград{/link} и не получил за это благодарности.]=],
		},
		{
			title = "Письмо гонца",
			hint = "Перехватите гонца Братства на дорогах Западного Края.",
			text = [=[Гонец Братства ездил по дорогам между {link:moonbrook}Луноречье{/link}м, каменоломней и Рудником Янго. Послание, которое он вез, стало твердым доказательством того, что Братством повелевает ван Клиф. Где он скрывается, в нем не говорилось.]=],
		},
		{
			title = "Убежище",
			hint = "Следуйте за предателем Братства к его логову.",
			text = [=[Пойманный вор купил себе жизнь, приведя ополчение в {link:moonbrook}Луноречье{/link}. Под деревней, в старом золотом руднике, ждал ван Клиф со своими каменщиками.]=],
		},
		{
			title = "Падение главаря",
			hint = "Спуститесь на дно Мертвых копей.",
			text = [=[На дне копей, на палубе своего корабля, ван Клиф встретил тех, кто пришел за ним. Он не сдался. Он созвал к себе стражу и бился так, как, по воспоминаниям архитектора {link:baros-alexston}Барос{/link}а Алекстона, бился в молодые годы, — не зная равных. Когда он пал, его голову отнесли на {link:sentinel-hill}Сторожевой холм{/link}.]=],
		},
		{
			title = "Неотправленное письмо",
			hint = "Обыщите тело главаря и доставьте то, что найдете.",
			text = [=[Среди вещей, которые носил при себе ван Клиф, было запечатанное письмо, так и не отправленное. Оно было адресовано {link:baros-alexston}Баросу Алекстону{/link}, городскому архитектору {link:stormwind-city}Штормград{/link}а. Барос знал его по гильдии. Прочитав письмо, он сказал, что ван Клиф по-прежнему идеалист и романтик — человек, которого поглотила месть. Он признался также, что не может всецело его винить.]=],
		},
	},
	mentions = {
		{
			text = [=[«{link:defias-brotherhood}Братство Справедливости{/link}», записка разбойника]=],
		},
		{
			text = [=[«{link:defias-brotherhood}Братство Справедливости{/link}», доставлено главе {link:si-7}SI:7{/link} Матиасу {link:master-mathias-shaw}Шоу{/link}]=],
		},
		{
			text = [=[«{link:bazil-thredd}Базиль Тредд{/link}», от архитектора {link:baros-alexston}Барос{/link}а Алекстона]=],
		},
		{ text = "«Красные шелковые банданы»" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Гриан Камнегрив", note = "охотится на него" },
		{ id = "baros-alexston", name = "Барос Алекстон", note = "некогда каменщик его гильдии" },
		{ id = "bazil-thredd", name = "Базиль Тредд", note = "его помощник" },
		{ id = "master-mathias-shaw", name = "мастер Матиас Шоу", note = "назвал его имя" },
		{ id = "tiffin-wrynn", name = "Тиффин Ринн", note = "погибла во время бунта, который он возглавил" },
		{ id = "captain-greenskin", name = "капитан Зеленокожий", note = "капитан его корабля" },
		{ id = "the-defias-traitor", name = "Предатель Братства Справедливости", note = "предал его" },
	},
})

